    _call_llm_provider_api,
    _get_provider_instance,
    _parse_model_uri,
    call_deployments_api,
)

_logger = logging.getLogger(__name__)

Route = Literal["databricks", "endpoints", "native", "litellm"]


class ScorerLLMClient:
    """Unified LLM backend client for scorer integrations.

    Determines the appropriate routing strategy from a model URI and the current
    environment, then dispatches ``complete`` calls to the corresponding backend.

    Routing rules:
        - ``"databricks"`` (or any bare name without ``/``) -> ``"databricks"``
        - ``"endpoints:/<endpoint>"`` -> ``"endpoints"``
        - ``"<provider>:/<model>"`` constructable by ``_get_provider_instance``
          (e.g. ``openai`` with ``OPENAI_API_KEY`` set, ``gateway``) -> ``"native"``
        - any other provider URI -> ``"litellm"``
    """

    def __init__(self, model_uri: str):
        self._model_uri = model_uri
        self._route: Route
        self._provider: Optional[str]
        self._raw_model_name: str
        self._model_name: str

        if ":/" not in model_uri:
            # Bare name, e.g. "databricks" or "gpt-oss-120b".
            self._route = "databricks"
            self._provider = None
            self._raw_model_name = model_uri
            self._model_name = model_uri
            return

        provider, raw_model_name = _parse_model_uri(model_uri)
        self._provider = provider
        self._raw_model_name = raw_model_name
        self._model_name = f"{provider}/{raw_model_name}"

        if provider == "endpoints":
            self._route = "endpoints"
            return

        # Use the native gateway provider if ``_get_provider_instance`` can construct
        # it (the required API keys are set, etc.); otherwise fall back to litellm.
        try:
            _get_provider_instance(provider, raw_model_name)
        except MlflowException:
            self._route = "litellm"
        else:
            self._route = "native"

    @property
    def model_uri(self) -> str:
        return self._model_uri

    @property
    def route(self) -> str:
        return self._route

    @property
    def is_native(self) -> bool:
        return self._route in ("databricks", "endpoints", "native")

    @property
    def model_name(self) -> str:
        return self._model_name

    @property
    def provider(self) -> Optional[str]:
        return self._provider

    @property
    def raw_model_name(self) -> str:
        return self._raw_model_name

    def _resolve_response_format(self, response_format: Any) -> Optional[dict[str, Any]]:
        if response_format is None:
            return None
        if isinstance(response_format, dict):
            return response_format
        if isinstance(response_format, type) and issubclass(response_format, pydantic.BaseModel):
            return pydantic_to_response_format(response_format)
        return response_format

    def _complete_once(
        self,
        messages: list[dict],
        response_format_dict: Optional[dict[str, Any]],
        **kwargs: Any,
    ) -> str:
        if self._route == "databricks":
            system_prompt = ""
            user_prompt = ""
            for message in messages:
                role = message.get("role")
                if role == "system":
                    system_prompt = message.get("content", "")
                elif role == "user":
                    user_prompt = message.get("content", "")
            result = databricks_managed_judge_adapter.call_chat_completions(
                user_prompt=user_prompt,
                system_prompt=system_prompt,
                model=self._model_uri,
            )
            return result.output

        if self._route == "endpoints":
            payload: dict[str, Any] = {"messages": messages}
            if kwargs:
                payload.update(kwargs)
            if response_format_dict is not None:
                payload["response_format"] = response_format_dict
            result = call_deployments_api(
                self._raw_model_name,
                payload,
                endpoint_type="llm/v1/chat",
            )
            if result is None:
                raise MlflowException("Empty response from deployment endpoint")
            return result

        if self._route == "native":
            return _call_llm_provider_api(
                self._provider,
                self._raw_model_name,
                messages=messages,
                eval_parameters=kwargs or None,
                response_format=response_format_dict,
            )

        # litellm route
        try:
            import litellm
        except ImportError as e:
            raise MlflowException.invalid_parameter_value(
                f"Model '{self._model_uri}' is not natively supported and requires the "
                "'litellm' package. Install it with `pip install litellm`."
            ) from e

        completion_kwargs = dict(kwargs)
        if response_format_dict is not None:
            completion_kwargs["response_format"] = response_format_dict
        response = litellm.completion(
            model=self._model_name,
            messages=messages,
            **completion_kwargs,
        )
        return response.choices[0].message.content

    def complete(
        self,
        messages: list[dict],
        response_format: Any = None,
        num_retries: int = 0,
        **kwargs: Any,
    ) -> str:
        response_format_dict = self._resolve_response_format(response_format)

        for attempt in range(num_retries + 1):
            try:
                return self._complete_once(messages, response_format_dict, **kwargs)
            except MlflowException:
                if attempt >= num_retries:
                    raise
                _logger.debug(
                    "LLM call failed (attempt %d/%d), retrying...",
                    attempt + 1,
                    num_retries + 1,
                )

    def complete_prompt(self, prompt: str) -> str:
        return self.complete([{"role": "user", "content": prompt}])
